export function getCanonicalDestinationData(slugOrId: string): CanonicalDestinationPackage | null {
  const clean = slugOrId.toLowerCase().replace(/^dest-/, '').trim();
  if (CANONICAL_REGISTRY_DATA[clean]) return CANONICAL_REGISTRY_DATA[clean];
  // Search by alias or name match
  for (const [key, pkg] of Object.entries(CANONICAL_REGISTRY_DATA)) {
    if (pkg.destination.slug === clean || pkg.destination.name.toLowerCase() === clean || key === clean) {
      return pkg;
    }
  }
  return null;
}
